import pytest
from requests.sessions import Session

def test_options_sets_default_allow_redirects_true():
    session = Session()
    # Mock the request method to capture arguments
    class MockResponse:
        pass
    def mock_request(method, url, **kwargs):
        assert method == 'OPTIONS'
        assert url == 'http://example.com'
        assert kwargs.get('allow_redirects') is True
        return MockResponse()
    session.request = mock_request
    response = session.options('http://example.com')
    assert isinstance(response, MockResponse)

def test_options_respects_explicit_allow_redirects_false():
    session = Session()
    class MockResponse:
        pass
    def mock_request(method, url, **kwargs):
        assert method == 'OPTIONS'
        assert url == 'http://example.com'
        assert kwargs.get('allow_redirects') is False
        return MockResponse()
    session.request = mock_request
    response = session.options('http://example.com', allow_redirects=False)
    assert isinstance(response, MockResponse)

def test_options_passes_through_other_kwargs():
    session = Session()
    class MockResponse:
        pass
    def mock_request(method, url, **kwargs):
        assert method == 'OPTIONS'
        assert url == 'http://example.com'
        assert kwargs.get('timeout') == 5
        assert kwargs.get('headers') == {'X-Test': 'value'}
        assert kwargs.get('allow_redirects') is True  # default still applied
        return MockResponse()
    session.request = mock_request
    response = session.options('http://example.com', timeout=5, headers={'X-Test': 'value'})
    assert isinstance(response, MockResponse)

def test_options_allows_overriding_allow_redirects_via_kwargs():
    session = Session()
    class MockResponse:
        pass
    def mock_request(method, url, **kwargs):
        assert method == 'OPTIONS'
        assert url == 'http://example.com'
        assert kwargs.get('allow_redirects') is False  # overridden
        return MockResponse()
    session.request = mock_request
    response = session.options('http://example.com', allow_redirects=False)
    assert isinstance(response, MockResponse)

