from django.views.generic.base import RedirectView
from django.http import HttpResponsePermanentRedirect, HttpResponseRedirect, HttpResponseGone
import logging

class TestRedirectView(RedirectView):
    def __init__(self, url=None, permanent=True):
        self._url = url
        self.permanent = permanent
        super().__init__()
    def get_redirect_url(self, *args, **kwargs):
        return self._url

def test_get_redirect_url_returns_url_permanent_true():
    view = TestRedirectView(url='/somewhere/', permanent=True)
    class Request:
        path = '/test/'
        META = {}
    resp = view.get(Request())
    assert isinstance(resp, HttpResponsePermanentRedirect)
    assert resp.url == '/somewhere/'

def test_get_redirect_url_returns_url_permanent_false():
    view = TestRedirectView(url='/somewhere/', permanent=False)
    class Request:
        path = '/test/'
        META = {}
    resp = view.get(Request())
    assert isinstance(resp, HttpResponseRedirect)
    assert resp.url == '/somewhere/'

def test_get_redirect_url_returns_none():
    view = TestRedirectView(url=None, permanent=True)
    class Request:
        path = '/test/'
        META = {}
    resp = view.get(Request())
    assert isinstance(resp, HttpResponseGone)

from requests.utils import get_encoding_from_headers

def test_no_content_type():
    assert get_encoding_from_headers({}) is None
    assert get_encoding_from_headers({'Content-Type': None}) is None  # get returns None
    assert get_encoding_from_headers({'content-type': ''}) is None  # empty string

def test_charset_present():
    headers = {'content-type': 'text/html; charset=UTF-8'}
    assert get_encoding_from_headers(headers) == 'UTF-8'
    # quoted charset
    headers = {'content-type': 'text/html; charset="ISO-8859-1"'}
    assert get_encoding_from_headers(headers) == 'ISO-8859-1'
    headers = {"content-type": "text/html; charset='utf-8'"}
    assert get_encoding_from_headers(headers) == 'utf-8'

def test_text_content_type_no_charset():
    headers = {'content-type': 'text/plain'}
    assert get_encoding_from_headers(headers) == 'ISO-8859-1'
    headers = {'content-type': 'text/html'}
    assert get_encoding_from_headers(headers) == 'ISO-8859-1'
    # 'text' appears elsewhere
    headers = {'content-type': 'application/vnd.api+json; charset=utf-8'}  # has charset, skip
    # Ensure no false positive: content-type containing 'text' as substring but not start? still counts
    headers = {'content-type': 'text/plain; charset=utf-8'}  # charset present, should return charset
    assert get_encoding_from_headers(headers) == 'utf-8'

def test_non_text_no_charset():
    headers = {'content-type': 'application/json'}
    assert get_encoding_from_headers(headers) is None
    headers = {'content-type': 'application/octet-stream'}
    assert get_encoding_from_headers(headers) is None
    headers = {'content-type': 'multipart/form-data'}
    assert get_encoding_from_headers(headers) is None
    # edge: content-type with 'text' but not as separate word? e.g. 'context/text' still contains 'text'
    headers = {'content-type': 'context/text'}
    assert get_encoding_from_headers(headers) == 'ISO-8859-1'

