    import pytest
    pytest.main([__file__])

import pytest
from sympy.series.sequences import SeqBase
from sympy import S, SeqFormula, SeqPer, symbols
from sympy.abc import n, m, a, b

def test_free_symbols_empty_sequence():
    # EmptySequence has no args
    assert S.EmptySequence.free_symbols == set()

def test_free_symbols_formula_only_dummy():
    # formula n**2, dummy n -> free symbols empty
    s = SeqFormula(n**2, (n, 0, 5))
    assert s.free_symbols == set()

def test_free_symbols_formula_extra_symbol():
    s = SeqFormula(m * n**2, (n, 0, 5))
    assert s.free_symbols == {m}

def test_free_symbols_limits_have_symbols():
    # limits contain symbols a,b besides dummy n
    s = SeqFormula(n**2, (n, a, b))
    # variables = (n,)
    # args: (n**2, (n, a, b))
    # free_symbols of n**2 -> {n}
    # free_symbols of (n, a, b) -> {n, a, b}
    # difference removes n -> {a, b} from second, first gives empty
    # union -> {a, b}
    assert s.free_symbols == {a, b}

def test_free_symbols_seqper():
    s = SeqPer((1, 2, 3), (n, 0, 5))
    # args: ((1,2,3), (n,0,5))
    # free_symbols of (1,2,3) -> empty
    # free_symbols of (n,0,5) -> {n}
    # variables = (n,) -> difference empty
    assert s.free_symbols == set()

def test_free_symbols_seqper_with_symbol_in_limits():
    s = SeqPer((1, 2, 3), (n, a, b))
    # free_symbols of limits -> {n, a, b}
    # diff -> {a, b}
    assert s.free_symbols == {a, b}

