from sympy.series.sequences import SeqBase
from sympy import Symbol

class DummySeq(SeqBase):
    def __init__(self, args, variables):
        self._args = args
        self._variables = variables
    @property
    def args(self):
        return self._args
    @property
    def variables(self):
        return self._variables

def test_free_symbols_basic():
    x = Symbol('x')
    y = Symbol('y')
    # args containing objects with free_symbols
    class Obj:
        def __init__(self, symbols):
            self.free_symbols = set(symbols)
    o1 = Obj([x])
    o2 = Obj([y])
    seq = DummySeq([o1, o2], {x})
    assert seq.free_symbols == {y}

def test_free_symbols_empty_args():
    seq = DummySeq([], {Symbol('x')})
    assert seq.free_symbols == set()

def test_free_symbols_vars_subset():
    x = Symbol('x')
    y = Symbol('y')
    class Obj:
        def __init__(self, symbols):
            self.free_symbols = set(symbols)
    o = Obj([x, y])
    seq = DummySeq([o], {x, y})
    assert seq.free_symbols == set()

def test_free_symbols_no_vars():
    x = Symbol('x')
    class Obj:
        def __init__(self, symbols):
            self.free_symbols = set(symbols)
    o = Obj([x])
    seq = DummySeq([o], set())
    assert seq.free_symbols == {x}

if __name__ == '__main__':
    test_free_symbols_basic()
    test_free_symbols_empty_args()
    test_free_symbols_vars_subset()
    test_free_symbols_no_vars()
    print('All passed')

