import logging
import django
from django.conf import settings
if not settings.configured:
    settings.configure()
from unittest import TestCase
from unittest.mock import patch, MagicMock
from django.views.generic.base import RedirectView
from django.http import (
    HttpResponsePermanentRedirect,
    HttpResponseRedirect,
    HttpResponseGone,
)

class TestRedirectViewGet(TestCase):
    def setUp(self):
        self.view = RedirectView()
        self.view.request = MagicMock()
        self.view.request.path = '/test'

    @patch('django.views.generic.base.logger')
    def test_get_redirect_url_returns_url_permanent_true(self, mock_logger):
        self.view.get_redirect_url = MagicMock(return_value='http://example.com')
        self.view.permanent = True
        resp = self.view.get(self.view.request)
        self.assertIsInstance(resp, HttpResponsePermanentRedirect)
        self.assertEqual(resp.url, 'http://example.com')
        mock_logger.warning.assert_not_called()

    @patch('django.views.generic.base.logger')
    def test_get_redirect_url_returns_url_permanent_false(self, mock_logger):
        self.view.get_redirect_url = MagicMock(return_value='http://example.com')
        self.view.permanent = False
        resp = self.view.get(self.view.request)
        self.assertIsInstance(resp, HttpResponseRedirect)
        self.assertEqual(resp.url, 'http://example.com')
        mock_logger.warning.assert_not_called()

    @patch('django.views.generic.base.logger')
    def test_get_redirect_url_returns_none(self, mock_logger):
        self.view.get_redirect_url = MagicMock(return_value=None)
        self.view.permanent = True  # doesn't matter
        resp = self.view.get(self.view.request)
        self.assertIsInstance(resp, HttpResponseGone)
        mock_logger.warning.assert_called_once_with(
            'Gone: %s', self.view.request.path,
            extra={'status_code': 410, 'request': self.view.request}
        )

    # Additional test for empty string? treat as falsy -> gone
    @patch('django.views.generic.base.logger')
    def test_get_redirect_url_returns_empty_string(self, mock_logger):
        self.view.get_redirect_url = MagicMock(return_value='')
        self.view.permanent = False
        resp = self.view.get(self.view.request)
        self.assertIsInstance(resp, HttpResponseGone)
        mock_logger.warning.assert_called_once_with(
            'Gone: %s', self.view.request.path,
            extra={'status_code': 410, 'request': self.view.request}
        )
